alter table public.award_spaces add column if not exists governance_score_monitoring_enabled boolean not null default true;
alter table public.award_spaces add column if not exists governance_score_drop_alert_threshold integer not null default 10 check(governance_score_drop_alert_threshold between 1 and 50);
create table if not exists public.election_governance_improvement_actions(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,component text not null check(component in('risk_review','incident_response','preventive_action','reporting','accountability','overall')),title text not null,description text not null,baseline_score integer check(baseline_score between 0 and 100),target_score integer check(target_score between 0 and 100),owner_id uuid references public.admins(id) on delete set null,target_date date,status text not null default 'open' check(status in('open','in_progress','completed','verified')),created_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now(),completed_at timestamptz,verified_at timestamptz,verified_by uuid references public.admins(id) on delete set null);
create index if not exists election_governance_improvement_actions_idx on public.election_governance_improvement_actions(award_space_id,status,target_date);
alter table public.election_governance_improvement_actions enable row level security;
